#!/usr/bin/env bash
set -Eeuo pipefail

if [[ ${EUID} -ne 0 ]]; then
  echo "Run this command with sudo: sudo rf-monitor configure" >&2
  exit 1
fi

STATE_FILE="${RFMON_STATE_FILE:-/etc/rf-monitor/install.conf}"
if [[ -r "${STATE_FILE}" ]]; then
  # Generated by the installer, root-owned, and limited to installation paths.
  source "${STATE_FILE}"
fi

INSTALL_DIR="${RFMON_INSTALL_DIR:-${INSTALL_DIR:-/opt/rf-monitor}}"
RELEASE_DIR="${RFMON_RELEASE_DIR:-${INSTALL_DIR}}"
DEFER_APPLICATION_ACTIVATION="${RFMON_DEFER_APPLICATION_ACTIVATION:-false}"
DATA_ROOT="${RFMON_DATA_ROOT:-${DATA_ROOT:-/var/lib/rf-monitor}}"
STORAGE_DIR="${RFMON_STORAGE_DIR:-${STORAGE_DIR:-${DATA_ROOT}/evidence}}"
RUNTIME_CONFIG_DIR="${RFMON_RUNTIME_CONFIG_DIR:-${RUNTIME_CONFIG_DIR:-${DATA_ROOT}/config}}"
CONFIG_DIR="${RFMON_CONFIG_DIR:-${CONFIG_DIR:-/etc/rf-monitor}}"
CONFIG_FILE="${RFMON_CONFIG_FILE:-${CONFIG_FILE:-/etc/rf-monitor.env}}"
CATALOG_FILE="${RFMON_CATALOG_FILE:-${CATALOG_FILE:-${CONFIG_DIR}/catalog.json}}"
OPERATIONAL_FILE="${RFMON_OPERATIONAL_FILE:-${OPERATIONAL_FILE:-${RUNTIME_CONFIG_DIR}/operational.json}}"
ADMIN_FILE="${RFMON_ADMIN_FILE:-${ADMIN_FILE:-${CONFIG_DIR}/admin.json}}"
SERVICE_USER="${RFMON_SERVICE_USER:-${SERVICE_USER:-rfmonitor}}"
SERVICE_GROUP="${RFMON_SERVICE_GROUP:-${SERVICE_GROUP:-rfmonitor}}"
NODE_BIN="${RFMON_NODE_BIN:-${NODE_BIN:-/usr/bin/node}}"
SERVICE_TEMPLATE="${RELEASE_DIR}/deploy/rf-monitor.service.template"
SERVICE_FILE="/etc/systemd/system/rf-monitor.service"
SDRCONNECT_BIN="${RFMON_SDRCONNECT_BIN:-${SDRCONNECT_BIN:-/opt/sdrconnect/SDRconnect_headless}}"
SDR_STATE_DIR="${RFMON_SDR_STATE_DIR:-${SDR_STATE_DIR:-${DATA_ROOT}/sdrconnect}}"
SDR_SERVICE_TEMPLATE="${RELEASE_DIR}/deploy/sdrconnect-headless.service.template"
SDR_SERVICE_FILE="/etc/systemd/system/sdrconnect-headless.service"
JOURNAL_CONFIG_FILE="${RFMON_JOURNAL_CONFIG_FILE:-${JOURNAL_CONFIG_FILE:-/etc/systemd/journald.conf.d/rf-monitor.conf}}"
STORAGE_ALLOWED_PREFIXES="${RFMON_STORAGE_ALLOWED_PREFIXES:-/var/lib:/srv:/mnt:/media:/data:/opt:/evidence}"
NONINTERACTIVE="${RFMON_NONINTERACTIVE:-false}"
ADVANCED="${RFMON_ADVANCED:-false}"

say() { printf '\n%s\n' "$*"; }
die() { echo "ERROR: $*" >&2; exit 1; }
sed_value() { printf '%s' "$1" | sed -e 's/[&|]/\\&/g'; }

for required_path in "${INSTALL_DIR}" "${RELEASE_DIR}" "${DATA_ROOT}" "${STORAGE_DIR}" "${RUNTIME_CONFIG_DIR}" "${CONFIG_DIR}" "${CONFIG_FILE}" "${CATALOG_FILE}" "${OPERATIONAL_FILE}" "${ADMIN_FILE}"; do
  [[ "${required_path}" = /* ]] || die "Installation and configuration paths must be absolute Linux paths."
  [[ "${required_path}" != *[[:space:]]* ]] || die "Installation and configuration paths cannot contain spaces."
done
[[ -x "${NODE_BIN}" ]] || die "System Node.js was not found at ${NODE_BIN}. Re-run the installer; do not use an NVM path."
[[ -f "${RELEASE_DIR}/dist/server-node/validate-config.js" ]] || die "RF Monitor is not built in ${RELEASE_DIR}. Re-run the installer."
[[ -f "${RELEASE_DIR}/dist/server-node/profile-seed.js" ]] || die "The operational-profile tool is missing. Re-run the installer."
[[ -f "${SERVICE_TEMPLATE}" ]] || die "Service template is missing: ${SERVICE_TEMPLATE}"
[[ "${DEFER_APPLICATION_ACTIVATION}" == "true" || "${DEFER_APPLICATION_ACTIVATION}" == "false" ]] \
  || die "RFMON_DEFER_APPLICATION_ACTIVATION must be true or false."

read_env_value() {
  local key="$1" fallback="$2" line value
  [[ -r "${CONFIG_FILE}" ]] || { printf '%s' "${fallback}"; return; }
  line="$(grep -E "^${key}=" "${CONFIG_FILE}" | tail -n 1 || true)"
  [[ -n "${line}" ]] || { printf '%s' "${fallback}"; return; }
  value="${line#*=}"
  if [[ "${value}" == \"*\" && "${value}" == *\" ]]; then
    value="${value:1:${#value}-2}"
    value="${value//\\\"/\"}"
    value="${value//\\\\/\\}"
  fi
  printf '%s' "${value}"
}

prompt_text() {
  local label="$1" default="$2" variable="$3" input=""
  if [[ "${NONINTERACTIVE}" != "true" ]]; then read -r -p "${label} [${default}]: " input; fi
  input="${input:-${default}}"
  [[ -n "${input}" && "${input}" != *$'\n'* && "${input}" != *$'\r'* ]] || die "${label} cannot be empty or contain a line break."
  printf -v "${variable}" '%s' "${input}"
}

prompt_integer() {
  local label="$1" default="$2" minimum="$3" variable="$4" input=""
  while true; do
    if [[ "${NONINTERACTIVE}" != "true" ]]; then read -r -p "${label} [${default}]: " input; fi
    input="${input:-${default}}"
    if [[ "${input}" =~ ^[0-9]+$ ]] && (( input >= minimum )); then printf -v "${variable}" '%s' "${input}"; return; fi
    echo "Enter a whole number greater than or equal to ${minimum}."
    input=""
  done
}

quote_value() {
  local value="$1"
  value="${value//\\/\\\\}"
  value="${value//\"/\\\"}"
  printf '"%s"' "${value}"
}

integer_or_default() {
  local value="$1" fallback="$2"
  if [[ "${value}" =~ ^[0-9]+$ ]]; then printf '%s' "${value}"; else printf '%s' "${fallback}"; fi
}

update_state() {
  local key="$1" value="$2" temporary
  [[ -r "${STATE_FILE}" ]] || return 0
  temporary="$(mktemp "${STATE_FILE}.XXXXXX")"
  grep -Ev "^${key}=" "${STATE_FILE}" > "${temporary}" || true
  printf '%s=%q\n' "${key}" "${value}" >> "${temporary}"
  install -m 0644 -o root -g root "${temporary}" "${STATE_FILE}"
  rm -f "${temporary}"
}

default_storage="$(realpath -m -- "$(read_env_value RF_MONITOR_STORAGE "${STORAGE_DIR}")")"
default_sdr_url="$(read_env_value SDRCONNECT_URL "ws://127.0.0.1:5454/")"
default_sdr_urls="$(read_env_value SDRCONNECT_URLS "${default_sdr_url}")"
default_device="$(read_env_value SDRCONNECT_DEVICE_INDEX "0")"
default_sample_rate="$(read_env_value SDRCONNECT_SAMPLE_RATE_HZ "10000000")"
default_backend_port="$(read_env_value RF_MONITOR_PORT "8080")"
default_iq_ms="$(read_env_value RF_MONITOR_IQ_CAPTURE_MS "0")"
default_admin_session="$(read_env_value RF_MONITOR_ADMIN_SESSION_MINUTES "15")"
default_journal_max_mib="${JOURNAL_MAX_USE_MIB:-512}"
default_journal_keep_free_mib="${JOURNAL_KEEP_FREE_MIB:-1024}"
default_journal_retention_days="${JOURNAL_RETENTION_DAYS:-14}"

say "RF Monitor guided configuration"
echo "Routine installations use safe local defaults. Monitoring services, site identity, time zone, thresholds, and retention are changed later in the protected Settings page."
if [[ "${ADVANCED}" == "true" ]]; then
  echo "Advanced infrastructure questions are enabled."
  prompt_text "Evidence storage directory (absolute Linux path)" "${default_storage}" REQUESTED_STORAGE_DIR
else
  REQUESTED_STORAGE_DIR="${default_storage}"
  echo "Evidence archive: ${REQUESTED_STORAGE_DIR}"
fi
REQUESTED_STORAGE_DIR="$(realpath -m -- "${REQUESTED_STORAGE_DIR}")"
storage_prefix_allowed=false
IFS=':' read -r -a storage_prefixes <<< "${STORAGE_ALLOWED_PREFIXES}"
for storage_prefix in "${storage_prefixes[@]}"; do
  canonical_prefix="$(realpath -m -- "${storage_prefix}")"
  if [[ "${REQUESTED_STORAGE_DIR}" == "${canonical_prefix}/"* ]]; then storage_prefix_allowed=true; break; fi
done
[[ "${storage_prefix_allowed}" == "true" ]] || die "Choose a dedicated subdirectory below one of these safe roots: ${STORAGE_ALLOWED_PREFIXES//:/, }."
if [[ "${REQUESTED_STORAGE_DIR}" != "${default_storage}" ]]; then
  echo "Existing evidence is not moved automatically. The previous archive remains at ${default_storage}."
  if [[ "${NONINTERACTIVE}" != "true" ]]; then
    read -r -p "Use the new empty archive path? [y/N]: " storage_answer
    [[ "${storage_answer}" =~ ^[Yy]$ ]] || die "Storage path change cancelled."
  fi
fi
STORAGE_DIR="${REQUESTED_STORAGE_DIR}"

install -d -m 0750 -o "${SERVICE_USER}" -g "${SERVICE_GROUP}" "${STORAGE_DIR}" "${RUNTIME_CONFIG_DIR}"
available_bytes="$(df -PB1 "${STORAGE_DIR}" | awk 'NR==2 {print $4}')"
available_gib=$(( available_bytes / 1073741824 ))
(( available_gib >= 4 )) || die "The evidence filesystem has less than 4 GiB free. Free space or choose another storage path."

if [[ "${ADVANCED}" == "true" ]]; then
  prompt_text "Local SDRconnect WebSocket URL" "${default_sdr_urls}" SDRCONNECT_URLS
else
  SDRCONNECT_URLS="${default_sdr_urls}"
  echo "SDRconnect API: ${SDRCONNECT_URLS}"
fi
SDRCONNECT_URLS="${SDRCONNECT_URLS//[[:space:]]/}"
IFS=',' read -r -a SDR_URL_ARRAY <<< "${SDRCONNECT_URLS}"
(( ${#SDR_URL_ARRAY[@]} > 0 )) || die "At least one SDRconnect URL is required."
(( ${#SDR_URL_ARRAY[@]} == 1 )) || die "RF Monitor 1.0 supports exactly one local RSPdx/SDRconnect endpoint."
for sdr_url in "${SDR_URL_ARRAY[@]}"; do
  [[ -n "${sdr_url}" && "${sdr_url}" =~ ^wss?:// ]] || die "Each SDRconnect URL must start with ws:// or wss://."
  "${NODE_BIN}" -e 'const u=new URL(process.argv[1]); if(!["ws:","wss:"].includes(u.protocol)||u.username||u.password||!["127.0.0.1","localhost","[::1]","::1"].includes(u.hostname.toLowerCase())) process.exit(1)' "${sdr_url}" \
    || die "Invalid SDRconnect URL: ${sdr_url}"
done
PRIMARY_SDRCONNECT_URL="${SDR_URL_ARRAY[0]}"
if [[ "${ADVANCED}" == "true" ]]; then
  prompt_integer "SDRconnect device index" "${default_device}" 0 SDR_DEVICE_INDEX
  prompt_integer "SDR sample rate in Hz" "${default_sample_rate}" 1000000 SDR_SAMPLE_RATE
  prompt_integer "IQ capture duration in milliseconds (must be 0 in spectrum-only v1)" "${default_iq_ms}" 0 IQ_CAPTURE_MS
  prompt_integer "Local RF Monitor backend port" "${default_backend_port}" 1024 BACKEND_PORT
  prompt_integer "Settings unlock duration in minutes" "${default_admin_session}" 1 ADMIN_SESSION_MINUTES
  prompt_integer "Maximum system service-log storage in MiB" "${default_journal_max_mib}" 64 JOURNAL_MAX_USE_MIB
  prompt_integer "Disk space kept free from system logs in MiB" "${default_journal_keep_free_mib}" 128 JOURNAL_KEEP_FREE_MIB
  prompt_integer "Maximum system service-log age in days" "${default_journal_retention_days}" 1 JOURNAL_RETENTION_DAYS
else
  SDR_DEVICE_INDEX="${default_device}"
  SDR_SAMPLE_RATE="${default_sample_rate}"
  IQ_CAPTURE_MS="${default_iq_ms}"
  BACKEND_PORT="${default_backend_port}"
  ADMIN_SESSION_MINUTES="${default_admin_session}"
  JOURNAL_MAX_USE_MIB="${default_journal_max_mib}"
  JOURNAL_KEEP_FREE_MIB="${default_journal_keep_free_mib}"
  JOURNAL_RETENTION_DAYS="${default_journal_retention_days}"
  echo "Receiver ${SDR_DEVICE_INDEX}; $(( SDR_SAMPLE_RATE / 1000000 )) MHz sample rate; local dashboard port ${BACKEND_PORT}."
fi
(( IQ_CAPTURE_MS == 0 )) || die "IQ capture is disabled in spectrum-only RF Monitor v1. Enter 0."

[[ -r "${CATALOG_FILE}" ]] || die "Frequency catalog not found: ${CATALOG_FILE}. Re-run the installer."
[[ -r "${ADMIN_FILE}" ]] || die "Settings password is not configured. Run: sudo rf-monitor reset-admin-password"
"${NODE_BIN}" -e 'const c=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")); if(c.schemaVersion!==1||c.algorithm!=="scrypt"||!c.hash||!c.sessionSecret) process.exit(1)' "${ADMIN_FILE}" \
  || die "Settings credential file is invalid. Run: sudo rf-monitor reset-admin-password"

say "Creating or preserving the operational monitoring profile"
suggested_max_bytes=$(( available_bytes * 70 / 100 ))
suggested_reserve_bytes=$(( available_bytes * 10 / 100 ))
suggested_session_bytes=$(( 2 * 1073741824 ))
(( suggested_session_bytes <= suggested_max_bytes )) || suggested_session_bytes=1073741824
initial_site="$(read_env_value RF_MONITOR_SITE_NAME "$(hostname -s) RF Monitor")"
initial_deployment="$(read_env_value RF_MONITOR_DEPLOYMENT_ID "$(hostname -s | tr '[:upper:]' '[:lower:]' | tr -cs 'a-z0-9._-' '-' | sed 's/-$//')-01")"
initial_timezone="$(read_env_value RF_MONITOR_DISPLAY_TIME_ZONE "$(timedatectl show --property=Timezone --value 2>/dev/null || echo UTC)")"
initial_session_bytes="$(integer_or_default "$(read_env_value RF_MONITOR_SESSION_MAX_BYTES "")" "${suggested_session_bytes}")"
initial_storage_bytes="$(integer_or_default "$(read_env_value RF_MONITOR_STORAGE_MAX_BYTES "")" "${suggested_max_bytes}")"
initial_reserve_bytes="$(integer_or_default "$(read_env_value RF_MONITOR_MIN_FREE_BYTES "")" "${suggested_reserve_bytes}")"
(( initial_storage_bytes >= initial_session_bytes )) || initial_storage_bytes="${initial_session_bytes}"
(( initial_reserve_bytes < available_bytes )) || initial_reserve_bytes="${suggested_reserve_bytes}"
legacy_bands="$(read_env_value RF_MONITOR_BANDS_FILE "")"
legacy_detection="$(read_env_value RF_MONITOR_DETECTION_FILE "")"
profile_environment=(
  "RFMON_INITIAL_SITE_NAME=${initial_site}"
  "RFMON_INITIAL_DEPLOYMENT_ID=${initial_deployment}"
  "RFMON_INITIAL_TIME_ZONE=${initial_timezone}"
  "RFMON_INITIAL_SESSION_MAX_BYTES=${initial_session_bytes}"
  "RFMON_INITIAL_SESSION_MAX_HOURS=$(integer_or_default "$(read_env_value RF_MONITOR_SESSION_MAX_HOURS "")" 24)"
  "RFMON_INITIAL_RETENTION_DAYS=$(integer_or_default "$(read_env_value RF_MONITOR_RETENTION_DAYS "")" 30)"
  "RFMON_INITIAL_STORAGE_MAX_BYTES=${initial_storage_bytes}"
  "RFMON_INITIAL_MIN_FREE_BYTES=${initial_reserve_bytes}"
)
[[ -n "${legacy_bands}" && -r "${legacy_bands}" ]] && profile_environment+=("RFMON_LEGACY_BANDS_FILE=${legacy_bands}")
[[ -n "${legacy_detection}" && -r "${legacy_detection}" ]] && profile_environment+=("RFMON_LEGACY_DETECTION_FILE=${legacy_detection}")
runuser -u "${SERVICE_USER}" -- env -i \
  "HOME=${DATA_ROOT}" \
  "PATH=/usr/bin:/bin" \
  "${profile_environment[@]}" \
  "${NODE_BIN}" "${RELEASE_DIR}/dist/server-node/profile-seed.js" \
  "${CATALOG_FILE}" "${RELEASE_DIR}/config/operational.example.json" "${OPERATIONAL_FILE}"
chown "${SERVICE_USER}:${SERVICE_GROUP}" "${OPERATIONAL_FILE}"
chmod 0640 "${OPERATIONAL_FILE}"

IQ_MAX_BYTES="$(integer_or_default "$(read_env_value RF_MONITOR_IQ_MAX_BYTES "")" 67108864)"
SDR_TIMEOUT="$(integer_or_default "$(read_env_value SDRCONNECT_TIMEOUT_MS "")" 5000)"

say "Validating the complete configuration"
validation_environment=(
  RF_MONITOR_REQUIRE_EXPLICIT_CONFIG=true
  RF_MONITOR_HOST=127.0.0.1
  "RF_MONITOR_PORT=${BACKEND_PORT}"
  "RF_MONITOR_STORAGE=${STORAGE_DIR}"
  "RF_MONITOR_CATALOG_FILE=${CATALOG_FILE}"
  "RF_MONITOR_OPERATIONAL_FILE=${OPERATIONAL_FILE}"
  "RF_MONITOR_ADMIN_FILE=${ADMIN_FILE}"
  "RF_MONITOR_ADMIN_SESSION_MINUTES=${ADMIN_SESSION_MINUTES}"
  RF_MONITOR_SIMULATION=off
  "RF_MONITOR_IQ_CAPTURE_MS=${IQ_CAPTURE_MS}"
  "RF_MONITOR_IQ_MAX_BYTES=${IQ_MAX_BYTES}"
  "SDRCONNECT_URLS=${SDRCONNECT_URLS}"
  "SDRCONNECT_TIMEOUT_MS=${SDR_TIMEOUT}"
  "SDRCONNECT_SAMPLE_RATE_HZ=${SDR_SAMPLE_RATE}"
  "SDRCONNECT_DEVICE_INDEX=${SDR_DEVICE_INDEX}"
  SDRCONNECT_TLS_REJECT_UNAUTHORIZED=true
)
runuser -u "${SERVICE_USER}" -- env -i \
  "HOME=${DATA_ROOT}" \
  "PATH=/usr/bin:/bin" \
  "${validation_environment[@]}" \
  "${NODE_BIN}" "${RELEASE_DIR}/dist/server-node/validate-config.js" >/dev/null

umask 077
temporary_config="$(mktemp "${CONFIG_FILE}.XXXXXX")"
{
  echo "# Generated by: sudo rf-monitor configure"
  echo "# Infrastructure only. Use the dashboard Settings page for monitoring and evidence policy."
  printf 'RF_MONITOR_REQUIRE_EXPLICIT_CONFIG=true\n'
  printf 'RF_MONITOR_HOST=127.0.0.1\n'
  printf 'RF_MONITOR_PORT=%s\n' "${BACKEND_PORT}"
  printf 'RF_MONITOR_STORAGE=%s\n' "$(quote_value "${STORAGE_DIR}")"
  printf 'RF_MONITOR_CATALOG_FILE=%s\n' "$(quote_value "${CATALOG_FILE}")"
  printf 'RF_MONITOR_OPERATIONAL_FILE=%s\n' "$(quote_value "${OPERATIONAL_FILE}")"
  printf 'RF_MONITOR_ADMIN_FILE=%s\n' "$(quote_value "${ADMIN_FILE}")"
  printf 'RF_MONITOR_ADMIN_SESSION_MINUTES=%s\n' "${ADMIN_SESSION_MINUTES}"
  if grep -qi microsoft /proc/sys/kernel/osrelease 2>/dev/null; then printf 'RF_MONITOR_WSL_TEST_MODE=true\n'; fi
  printf 'RF_MONITOR_SIMULATION=off\n'
  printf 'RF_MONITOR_IQ_CAPTURE_MS=%s\n' "${IQ_CAPTURE_MS}"
  printf 'RF_MONITOR_IQ_MAX_BYTES=%s\n' "${IQ_MAX_BYTES}"
  printf 'SDRCONNECT_URL=%s\n' "$(quote_value "${PRIMARY_SDRCONNECT_URL}")"
  if (( ${#SDR_URL_ARRAY[@]} > 1 )); then printf 'SDRCONNECT_URLS=%s\n' "$(quote_value "${SDRCONNECT_URLS}")"; fi
  printf 'SDRCONNECT_TIMEOUT_MS=%s\n' "${SDR_TIMEOUT}"
  printf 'SDRCONNECT_SAMPLE_RATE_HZ=%s\n' "${SDR_SAMPLE_RATE}"
  printf 'SDRCONNECT_DEVICE_INDEX=%s\n' "${SDR_DEVICE_INDEX}"
  printf 'SDRCONNECT_TLS_REJECT_UNAUTHORIZED=true\n'
  existing_ca="$(read_env_value NODE_EXTRA_CA_CERTS "")"
  [[ -n "${existing_ca}" ]] && printf 'NODE_EXTRA_CA_CERTS=%s\n' "$(quote_value "${existing_ca}")"
  existing_origins="$(read_env_value RF_MONITOR_ALLOWED_ORIGINS "")"
  [[ -n "${existing_origins}" ]] && printf 'RF_MONITOR_ALLOWED_ORIGINS=%s\n' "$(quote_value "${existing_origins}")"
} > "${temporary_config}"
if [[ -f "${CONFIG_FILE}" ]]; then cp -a "${CONFIG_FILE}" "${CONFIG_FILE}.backup-$(date --utc +%Y%m%dT%H%M%SZ)"; fi
install -m 0600 -o root -g root "${temporary_config}" "${CONFIG_FILE}"
rm -f "${temporary_config}"

install -d -m 0755 -o root -g root "$(dirname "${JOURNAL_CONFIG_FILE}")"
temporary_journal="$(mktemp "${JOURNAL_CONFIG_FILE}.XXXXXX")"
{
  echo "# Generated by: sudo rf-monitor configure"
  echo "[Journal]"
  printf 'SystemMaxUse=%sM\n' "${JOURNAL_MAX_USE_MIB}"
  printf 'SystemKeepFree=%sM\n' "${JOURNAL_KEEP_FREE_MIB}"
  printf 'MaxRetentionSec=%sday\n' "${JOURNAL_RETENTION_DAYS}"
  echo "MaxFileSec=1day"
} > "${temporary_journal}"
install -m 0644 -o root -g root "${temporary_journal}" "${JOURNAL_CONFIG_FILE}"
rm -f "${temporary_journal}"
systemctl restart systemd-journald.service

if [[ "${DEFER_APPLICATION_ACTIVATION}" != "true" ]]; then
  sed \
    -e "s|@@SERVICE_USER@@|$(sed_value "${SERVICE_USER}")|g" \
    -e "s|@@SERVICE_GROUP@@|$(sed_value "${SERVICE_GROUP}")|g" \
    -e "s|@@INSTALL_DIR@@|$(sed_value "${INSTALL_DIR}")|g" \
    -e "s|@@CONFIG_FILE@@|$(sed_value "${CONFIG_FILE}")|g" \
    -e "s|@@NODE_BIN@@|$(sed_value "${NODE_BIN}")|g" \
    -e "s|@@STORAGE_DIR@@|$(sed_value "${STORAGE_DIR}")|g" \
    -e "s|@@RUNTIME_CONFIG_DIR@@|$(sed_value "${RUNTIME_CONFIG_DIR}")|g" \
    "${SERVICE_TEMPLATE}" > "${SERVICE_FILE}"
  chmod 0644 "${SERVICE_FILE}"
fi

primary_sdr_host="$("${NODE_BIN}" -e 'console.log(new URL(process.argv[1]).hostname)' "${PRIMARY_SDRCONNECT_URL}")"
primary_sdr_port="$("${NODE_BIN}" -e 'const u=new URL(process.argv[1]); console.log(u.port||(u.protocol==="wss:"?"443":"80"))' "${PRIMARY_SDRCONNECT_URL}")"
if [[ "${primary_sdr_host}" == "127.0.0.1" || "${primary_sdr_host}" == "localhost" || "${primary_sdr_host}" == "[::1]" ]]; then
  if [[ -x "${SDRCONNECT_BIN}" && -f "${SDR_SERVICE_TEMPLATE}" ]]; then
    install -d -m 0750 -o "${SERVICE_USER}" -g "${SERVICE_GROUP}" "${SDR_STATE_DIR}"
    sed \
      -e "s|@@SERVICE_USER@@|$(sed_value "${SERVICE_USER}")|g" \
      -e "s|@@SERVICE_GROUP@@|$(sed_value "${SERVICE_GROUP}")|g" \
      -e "s|@@SDR_STATE_DIR@@|$(sed_value "${SDR_STATE_DIR}")|g" \
      -e "s|@@SDRCONNECT_BIN@@|$(sed_value "${SDRCONNECT_BIN}")|g" \
      -e "s|@@SDRCONNECT_PORT@@|$(sed_value "${primary_sdr_port}")|g" \
      "${SDR_SERVICE_TEMPLATE}" > "${SDR_SERVICE_FILE}"
    chmod 0644 "${SDR_SERVICE_FILE}"
  else
    echo "WARNING: Local SDRconnect was selected but its headless executable is missing: ${SDRCONNECT_BIN}"
  fi
elif systemctl is-enabled --quiet sdrconnect-headless.service 2>/dev/null; then
  systemctl disable --now sdrconnect-headless.service
fi

if command -v ufw >/dev/null 2>&1; then
  for configured_sdr_url in "${SDR_URL_ARRAY[@]}"; do
    configured_sdr_host="$("${NODE_BIN}" -e 'console.log(new URL(process.argv[1]).hostname)' "${configured_sdr_url}")"
    if [[ "${configured_sdr_host}" == "127.0.0.1" || "${configured_sdr_host}" == "localhost" || "${configured_sdr_host}" == "[::1]" ]]; then
      configured_sdr_port="$("${NODE_BIN}" -e 'const u=new URL(process.argv[1]); console.log(u.port||(u.protocol==="wss:"?"443":"80"))' "${configured_sdr_url}")"
      ufw deny "${configured_sdr_port}/tcp" >/dev/null || true
    fi
  done
  ufw deny "${BACKEND_PORT}/tcp" >/dev/null || true
fi

systemctl daemon-reload
update_state STORAGE_DIR "${STORAGE_DIR}"
update_state RUNTIME_CONFIG_DIR "${RUNTIME_CONFIG_DIR}"
update_state CATALOG_FILE "${CATALOG_FILE}"
update_state OPERATIONAL_FILE "${OPERATIONAL_FILE}"
update_state ADMIN_FILE "${ADMIN_FILE}"
update_state JOURNAL_CONFIG_FILE "${JOURNAL_CONFIG_FILE}"
update_state JOURNAL_MAX_USE_MIB "${JOURNAL_MAX_USE_MIB}"
update_state JOURNAL_KEEP_FREE_MIB "${JOURNAL_KEEP_FREE_MIB}"
update_state JOURNAL_RETENTION_DAYS "${JOURNAL_RETENTION_DAYS}"
current_public_url="${PUBLIC_URL:-}"
if [[ -z "${current_public_url}" || "${current_public_url}" == http://127.0.0.1:* ]]; then update_state PUBLIC_URL "http://127.0.0.1:${BACKEND_PORT}/"; fi

# Refuse to take over a local API port from SDRconnect GUI or any unrelated process.
if [[ "${primary_sdr_host}" == "127.0.0.1" || "${primary_sdr_host}" == "localhost" || "${primary_sdr_host}" == "[::1]" ]]; then
  listener_pid="$(ss -ltnpH "sport = :${primary_sdr_port}" 2>/dev/null | sed -nE 's/.*pid=([0-9]+).*/\1/p' | head -n 1)"
  managed_pid="$(systemctl show --property=MainPID --value sdrconnect-headless.service 2>/dev/null || true)"
  if [[ -n "${listener_pid}" && "${listener_pid}" != "0" && "${listener_pid}" != "${managed_pid}" ]]; then
    listener_name="$(ps -p "${listener_pid}" -o comm= 2>/dev/null || echo unknown)"
    die "SDRconnect API port ${primary_sdr_port} is already owned by ${listener_name} (PID ${listener_pid}), not sdrconnect-headless.service. Close SDRconnect GUI or choose Advanced configuration with a different port; RF Monitor will not stop it automatically."
  fi
fi

services_restarted=false
if systemctl is-enabled --quiet sdrconnect-headless.service 2>/dev/null && [[ -f "${SDR_SERVICE_FILE}" ]]; then systemctl restart sdrconnect-headless.service; services_restarted=true; fi
if [[ "${DEFER_APPLICATION_ACTIVATION}" != "true" ]] && systemctl is-enabled --quiet rf-monitor.service 2>/dev/null; then
  systemctl restart rf-monitor.service
  services_restarted=true
fi

say "Configuration saved"
echo "Infrastructure: ${CONFIG_FILE}"
echo "Frequency catalog: ${CATALOG_FILE}"
echo "Operational profile: ${OPERATIONAL_FILE}"
echo "Evidence archive: ${STORAGE_DIR}"
echo "System logs: ${JOURNAL_CONFIG_FILE} (${JOURNAL_MAX_USE_MIB} MiB, ${JOURNAL_RETENTION_DAYS} days)"
[[ "${services_restarted}" == "true" ]] && echo "Enabled services were restarted."
echo
echo "Next commands:"
echo "  sudo rf-monitor doctor"
echo "  sudo rf-monitor access"
echo "Then open Settings in the dashboard to choose services, frequencies, site name, time zone, and retention."
